    distance[source] = 0
    previous = {node: None for node in graph}
    queue = deque([source])
    while queue:
        current = queue.popleft()
        if current == target:
            path = []
            while current is not None:
                path.append(current)
                current = previous[current]
            return (distance[target], list(reversed(path)))
